function dryden = build_dryden_filter(V, Lw, sigmaW, tau)
%BUILD_DRYDEN_FILTER Build vertical Dryden turbulence dynamics with an LPF.
%
% The physical gust velocity is generated by
%
%   Wg(s)       b1*s + b0             1
%   ----- = ------------------- * ---------
%   Ug(s)   s^2 + a1*s + a0       tau*s + 1
%
% and the returned output matrix maps the filter states to [w_g; wdot_g].

arguments
    V (1,1) double {mustBePositive}
    Lw (1,1) double {mustBePositive}
    sigmaW (1,1) double {mustBeNonnegative}
    tau (1,1) double {mustBePositive}
end

a1 = V/Lw;
a0 = (V/(2*Lw))^2;
b1 = sigmaW*V*sqrt(3/(2*pi*Lw));
b0 = sigmaW*V^2/(2*sqrt(2*pi)*Lw^(3/2));

% Normalize the combined third-order denominator to a monic polynomial.
den = conv([1, a1, a0], [tau, 1]);
den = den/den(1);

% Controllable companion realization. For this state ordering,
% x1/U = 1/den(s), x2/U = s/den(s), and x3/U = s^2/den(s).
Aw = [ ...
     0,       1,       0;
     0,       0,       1;
    -den(4), -den(3), -den(2)];
Bw = [0; 0; 1];

Cwg = [b0/tau, b1/tau, 0];
Cwdot = Cwg*Aw;

if abs(Cwg*Bw) > 100*eps
    error('Dryden realization has unexpected direct feedthrough in w_g.');
end

Cw = [Cwg; Cwdot];
Dw = zeros(2,1);

if any(real(eig(Aw)) >= 0)
    error('Dryden shaping filter is not asymptotically stable.');
end

% Expected covariance for continuous unit-intensity white-noise input.
stateCovariance = lyap(Aw, Bw*Bw.');
unitNoiseRmsWg = sqrt(max(Cwg*stateCovariance*Cwg.', 0));
if sigmaW == 0
    inputNoiseScale = 0;
elseif unitNoiseRmsWg <= 0
    error('Could not normalize the Dryden filter to the requested sigma_w.');
else
    inputNoiseScale = sigmaW/unitNoiseRmsWg;
end

dryden = struct();
dryden.A = Aw;
dryden.B = Bw;
dryden.C = Cw;
dryden.D = Dw;
dryden.a0 = a0;
dryden.a1 = a1;
dryden.b0 = b0;
dryden.b1 = b1;
dryden.V = V;
dryden.Lw = Lw;
dryden.sigmaW = sigmaW;
dryden.tau = tau;
dryden.stateCovariance = stateCovariance;
dryden.unitNoiseRmsWg = unitNoiseRmsWg;
dryden.inputNoiseScale = inputNoiseScale;
dryden.expectedRmsWg = inputNoiseScale*unitNoiseRmsWg;

end
